StructuredTextModel.Text:
(*
  SENSOR READING PROGRAM
  Reads pressure and flow sensors, applies physics-based nozzle model
  Author: AhmadMohammad | Date: 2025-11-05
  
  REVISIONS:
  V2.1.0		-		2025-11-05		-		AM		-		Independent pressure and turbine flows
*)

// PRESSURE CALCULATION
IF IFM_P1_Device_Error OR IFM_P1_Communication_Error THEN
    iPressure_mBar := 0;
ELSE
    wPressure := SHL(BYTE_TO_WORD(IFM_P1_Pressure_high), 8) 
                 OR BYTE_TO_WORD(IFM_P1_Pressure_low);
    
    iPressure_Raw := WORD_TO_INT(wPressure);
    
    iPressure_mBar := LREAL_TO_INT(INT_TO_LREAL(iPressure_Raw) / 32767.0 * 10000.0);
    
    IF iPressure_mBar < -1000 THEN
        iPressure_mBar := -1000;
    END_IF;
    
    IF iPressure_mBar > 10000 THEN
        iPressure_mBar := 10000;
    END_IF;
    
    rPressure_Bar := INT_TO_LREAL(iPressure_mBar) / 1000.0;
END_IF;

// FLOW CALCULATION - PHYSICS-BASED MODEL
// Q = sqrt(Ps / (α + β))
// Primary flow from pressure sensor, secondary from turbine sensor

IF An_Flow < 0 THEN
    rFlow_LperMin := 0.0;
    rFlow_mA := 0.0;
    rFlow_LperMin_TurbineRef := 0.0;

ELSIF An_Flow > 37683 THEN
    rFlow_LperMin := 1.5;
    rFlow_mA := 20.0;
    rFlow_LperMin_TurbineRef := 1.5;

ELSIF An_Flow > 32767 THEN
    rFlow_LperMin := 1.5;
    rFlow_mA := 20.0;
    rFlow_LperMin_TurbineRef := 1.5;

ELSE
    // PRIMARY: Flow from pressure model (independent)
    rFlow_LperMin := GetFlowFromPressure(iFluid_Selected, iNozzle_Selected, rPressure_Bar);
    
    // REFERENCE: Flow from turbine sensor (independent)
    rFlow_LperMin_TurbineRef := 0.05 + (INT_TO_LREAL(An_Flow) / 8400.0) * 1.45;
    
    // mA output
    rFlow_mA := 4.0 + (INT_TO_LREAL(An_Flow) / 8400.0) * 16.0;
    
    // SAFETY CLIPPING (pressure flow only)
    IF rFlow_LperMin < 0.05 THEN
        rFlow_LperMin := 0.0;
    END_IF;
    
    IF rFlow_LperMin > 1.5 THEN
        rFlow_LperMin := 1.5;
    END_IF;
    
    // AUTO-CALIBRATION: Continuous α refinement
    IF rFlow_LperMin_TurbineRef > 0.1 AND rFlow_LperMin_TurbineRef < 1.5 AND rPressure_Bar >= 0.0 THEN
        
        rBeta_Current := GetBeta(iFluid_Selected, iNozzle_Selected);
        rQ_TurbineRef_Sq := rFlow_LperMin_TurbineRef * rFlow_LperMin_TurbineRef;
        
        IF rQ_TurbineRef_Sq > 0.01 THEN
            rAlpha_Measured := (rPressure_Bar / rQ_TurbineRef_Sq) - rBeta_Current;
            
            IF rAlpha_Measured < 0.0 THEN
                rAlpha_Measured := 0.0;
            END_IF;
            IF rAlpha_Measured > 100.0 THEN
                rAlpha_Measured := 100.0;
            END_IF;
            
            CASE iFluid_Selected OF
                0:
                    rAlpha_Drift := ABS(rAlpha_Measured - rAlpha_Previous_W);
                    IF rAlpha_Drift > rAlpha_DriftThreshold THEN
                        bAlpha_DriftDetected := TRUE;
                    ELSE
                        bAlpha_DriftDetected := FALSE;
                    END_IF;
                    rAlpha_Water := (rAlpha_TauFactor * rAlpha_Measured) + ((1.0 - rAlpha_TauFactor) * rAlpha_Previous_W);
                    rAlpha_Previous_W := rAlpha_Water;
                
                1:
                    rAlpha_Drift := ABS(rAlpha_Measured - rAlpha_Previous_X);
                    IF rAlpha_Drift > rAlpha_DriftThreshold THEN
                        bAlpha_DriftDetected := TRUE;
                    ELSE
                        bAlpha_DriftDetected := FALSE;
                    END_IF;
                    rAlpha_ISOXEL := (rAlpha_TauFactor * rAlpha_Measured) + ((1.0 - rAlpha_TauFactor) * rAlpha_Previous_X);
                    rAlpha_Previous_X := rAlpha_ISOXEL;
                
                2:
                    rAlpha_Drift := ABS(rAlpha_Measured - rAlpha_Previous_D);
                    IF rAlpha_Drift > rAlpha_DriftThreshold THEN
                        bAlpha_DriftDetected := TRUE;
                    ELSE
                        bAlpha_DriftDetected := FALSE;
                    END_IF;
                    rAlpha_DFAB := (rAlpha_TauFactor * rAlpha_Measured) + ((1.0 - rAlpha_TauFactor) * rAlpha_Previous_D);
                    rAlpha_Previous_D := rAlpha_DFAB;
            END_CASE;
        END_IF;
    END_IF;
    
END_IF;

// TOTAL VOLUME INTEGRATION
IF rTotalVolume_L = 0.0 AND rPrevFlow = 0.0 THEN
    rTotalVolume_L := 0.0;
    rPrevFlow := 0.0;
END_IF;

tmrFlowSample(IN := TRUE, PT := tSampleTime);

IF bTotalReset AND NOT bTotalReset_mem THEN
    rTotalVolume_L := 0.0;
END_IF;

bTotalReset_mem := bTotalReset;

IF tmrFlowSample.Q THEN
    rTotalVolume_L := rTotalVolume_L
    + ((rFlow_LperMin + rPrevFlow) / 2.0)
    * (100.0 / 60000.0);
    rPrevFlow := rFlow_LperMin;
    tmrFlowSample(IN := FALSE);
END_IF;
